record Payout(String merchantId, BigDecimal gross, BigDecimal fee, BigDecimal net) {}
record Ledger(List<Entry> entries) {
    Ledger { entries = List.copyOf(entries); }                // snapshot: nobody can change it later
    Ledger posting(List<Entry> more) {                        // a new version, by copying everything
        List<Entry> all = new ArrayList<>(entries);
        all.addAll(more);
        return new Ledger(all);
    }
}

static BigDecimal fee(BigDecimal gross, BigDecimal rate) {   // pure: same inputs, same output
    return gross.multiply(rate).setScale(2, RoundingMode.HALF_EVEN);
}

