fun decide(cases: List<Case>, today: LocalDate): List<CaseAction> = cases.map { case ->
    val daysLeft = ChronoUnit.DAYS.between(today, case.deadline)
    when {
        daysLeft < 0 -> CaseAction.AcceptLoss(case.id)
        daysLeft <= 2 && !case.evidenceSent -> CaseAction.Escalate(case.id, daysLeft)
        else -> CaseAction.Wait(case.id)
    }
}

