tailrec fun originOf(id: String, byId: Map<String, Txn>): String {
    val parent = byId.getValue(id).parentId ?: return id   // no parent: this is the original
    return originOf(parent, byId)                          // the last thing the function does
}
// A log line after the call makes it no longer a tail call: Kotlin warns
// "Recursive call is not a tail call." and compiles ordinary recursion, which can overflow.

