static String originOf(String id, Map<String, Txn> byId) {
    String current = id;
    while (true) {
        String parent = byId.get(current).parentId();
        if (parent == null) return current;   // no parent: this is the original
        current = parent;                     // what tailrec's goto does
    }
}
